    source:
      '//! Owned arbitrary bytes for file contents, process output, and other encoding-neutral data.\n//!\n//! # When to use\n//! Use [`Bytes`] when every octet must round-trip unchanged. Use `silk.string.String` instead when\n//! the value is known to be valid UTF-8 and callers need text operations.\n//!\n//! # Details\n//! [`make`] creates an empty value without allocating, while [`zeroed`], [`copy`], and [`append`]\n//! may require an [`Allocator`]. Shared and exclusive views borrow only the initialized prefix;\n//! later appends can reallocate, so do not retain a view across a mutation.\n\nimport silk.core { Allocator }\nimport silk.core { OutOfMemoryError }\nimport silk.u8 as u8\nimport silk.usize as usize\nimport silk.vector {\n  Vector,\n  make as vectorMake,\n  append as vectorAppend,\n  appendBytes as vectorAppendBytes,\n  length as vectorLength,\n  asSlice as vectorAsSlice,\n  asMutSlice as vectorAsMutSlice\n}\n\n/// An owned encoding-neutral sequence of arbitrary octets.\npub struct Bytes {\n  values: Vector<u8>\n}\n\n/// Constructs empty Bytes without allocating.\npub fn make() -> Bytes {\n  return Bytes { values: vectorMake<u8>() }\n}\n\n/// Allocates an owned initialized byte buffer of exactly `length` zero octets.\npub effect fn zeroed(length: usize) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n  let mut result = make()\n  let mut index = usize.ZERO\n  while index < length {\n    let appended = run vectorAppend<u8>(&mut result.values, u8.toU8(0))\n    index = index + usize.ONE\n  }\n  return move result\n}\n\n/// Returns the initialized byte count.\npub fn length(self: &Bytes) -> usize {\n  return vectorLength<u8>(&self.values)\n}\n\n/// Copies one borrowed byte sequence into independently owned storage.\npub effect fn copy(values: &[u8]) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n  let mut result = make()\n  let appended = run append(&mut result, values)\n  return move result\n}\n\n/// Appends one complete borrowed byte sequence in source order with one bulk copy.\npub effect fn append(self: &mut Bytes, values: &[u8]) -> () ! OutOfMemoryError ? &mut Allocator {\n  let appended = run vectorAppendBytes(&mut self.values, values)\n  return ()\n}\n\n/// Borrows the initialized octets as one shared lexical slice.\npub fn asSlice(self: &Bytes) -> &[u8] {\n  return vectorAsSlice<u8>(&self.values)\n}\n\n/// Borrows the initialized octets as one exclusive lexical slice.\npub fn asMutSlice(self: &mut Bytes) -> &mut [u8] {\n  return vectorAsMutSlice<u8>(&mut self.values)\n}\n',
