    source:
      '//! Checked construction, integer inspection, equality, and ordering for Unicode scalar `char`\n//! values.\n//!\n//! # When to use\n//! Prefer comparison operators in direct expressions. Import these functions when comparison must\n//! be passed by name or when the Unicode scalar ordering should be explicit at a call site.\n//!\n//! # Details\n//! Ordering compares scalar values, not locale collation, normalization, grapheme clusters, or UTF-8\n//! byte sequences. These allocation-free functions call the same primitives as the corresponding\n//! operators and introduce no Effect channels.\n\nimport silk.bool as bool\nimport silk.option { Option }\nimport silk.u32 as u32\n\n/// Converts an integer to a Unicode scalar, returning None for surrogates or out-of-range values.\npub fn fromU32(value: u32) -> Option<char> {\n  return Intrinsic.charFromU32(value)\n}\n\n/// Returns the exact integer value of an already valid Unicode scalar.\npub fn toU32(value: char) -> u32 {\n  return Intrinsic.charToU32(value)\n}\n\n/// Returns `true` when `left` and `right` are the same Unicode scalar value.\npub fn equals(left: char, right: char) -> bool {\n  return Intrinsic.charEquals(left, right)\n}\n\n/// Returns `true` when `left` and `right` are different Unicode scalar values.\npub fn notEquals(left: char, right: char) -> bool {\n  return Intrinsic.charNotEquals(left, right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is less than `right`.\npub fn lessThan(left: char, right: char) -> bool {\n  return Intrinsic.charLessThan(&left, &right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is less than or equal to `right`.\npub fn lessOrEqual(left: char, right: char) -> bool {\n  return Intrinsic.charLessOrEqual(left, right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is greater than `right`.\npub fn greaterThan(left: char, right: char) -> bool {\n  return Intrinsic.charGreaterThan(left, right)\n}\n\n/// Returns `true` when the Unicode scalar value of `left` is greater than or equal to `right`.\npub fn greaterOrEqual(left: char, right: char) -> bool {\n  return Intrinsic.charGreaterOrEqual(left, right)\n}\n',
