    source:
      "//! Deterministic seeded hashing contracts for hash maps, hash sets, and user-defined key types.\n//!\n//! # When to use\n//! Implement [`HashKey`] when a type will be stored as a hashed key. Use [`mix`] for the first\n//! integer field and [`combine`] for further fields, feeding every field that participates in\n//! equality. [`Word`] is the ready-made key for one `u64`.\n//!\n//! # Details\n//! A [`HashSeed`] belongs to a collection, not to each key. The same seed, keys, and operations\n//! produce the same bucket presentation order on every engine, independent of addresses or ambient\n//! state. Interface witnesses are selected during specialization and add no runtime dispatch.\n//!\n//! # Gotchas\n//! Whenever `HashKey.equals` reports two values equal, `HashKey.hash` must return the same value\n//! for both under every seed. The collection cannot detect a witness that violates this rule; such\n//! a key may become unreachable.\n\n// The hashing contract the hashed collections resolve against, and the seed every hash is computed\n// under. Ordinary Silk: no compiler phase computes a hash, recognizes this interface by spelling, or\n// treats a conformance to it as anything other than an ordinary conformance.\n//\n// The contract pairs an equivalence with a hash because a hashed collection needs both and needs\n// them to agree. The equivalence is named `equals` rather than `equivalent` for the same reason\n// `order.silk` declares `lessThan` rather than a three-way `compare`: an interface operation is\n// reachable from a generic body through the operator that spells it, and `==` spells `equals`. The\n// hash is reached by naming the bound, which is the one call shape no operator provides.\n\nimport silk.bool as bool\nimport silk.u64 as u64\n\n/// The value every hash in one collection is computed under.\n///\n/// # Details\n///\n/// One seed fixes one iteration order. A collection consults nothing else — no allocation address,\n/// no clock, no ambient entropy — so two runs of one program over one seed observe one order, and\n/// they observe it identically on the evaluator, on the native backend, and on WebAssembly.\npub struct HashSeed {\n  /// The seed value handed to every hash the collection computes.\n  pub value: u64\n}\n\nimpl Copy for HashSeed {}\n\n/// Constructs a seed from one value.\npub fn seed(value: u64) -> HashSeed {\n  return HashSeed { value: value }\n}\n\n/// Static hashing contract for a key of a hashed collection.\n///\n/// # Details\n///\n/// A witness supplies two operations over one key type: the equivalence `==` spells, and a hash of\n/// one key under one seed. The seed is an operand of the hash rather than state a key carries,\n/// because one seed serves the whole collection.\n///\n/// # Gotchas\n///\n/// A witness must compute equal hashes for two keys its own `equals` reports equivalent, under every\n/// seed. Nothing checks this — a witness that breaks it makes a present key unreachable, and a\n/// collection can neither detect the breakage nor recover from it.\npub interface HashKey {\n  /// Reports whether two keys name the same collection entry.\n  operator == fn equals(left: &Self, right: &Self) -> bool\n  /// Computes the key's deterministic 64-bit hash under the collection seed.\n  fn hash(value: &Self, seed: &HashSeed) -> u64\n}\n\n/// Mixes one value under one seed into a hash spread across the whole 64-bit range.\n///\n/// # Details\n///\n/// Every step is a wrapping multiply, a shift, or an exclusive or, so the result is exactly the same\n/// on every engine. A witness for a key built from integers can answer `hash` by folding its fields\n/// through this function rather than inventing a mixer.\npub fn mix(seed: &HashSeed, value: u64) -> u64 {\n  let salted = u64.wrappingAdd(value, seed.value)\n  let stepped = u64.wrappingAdd(salted, 11400714819323198485)\n  let folded = u64.bitXor(stepped, u64.shiftRight(stepped, 30))\n  let spread = u64.wrappingMultiply(folded, 13787848793156543929)\n  let refolded = u64.bitXor(spread, u64.shiftRight(spread, 27))\n  let respread = u64.wrappingMultiply(refolded, 10723151780598845931)\n  return u64.bitXor(respread, u64.shiftRight(respread, 31))\n}\n\n/// Continues a hash with one further value, so a key of several fields folds into one hash.\npub fn combine(hashed: u64, value: u64) -> u64 {\n  let mingled = u64.bitXor(hashed, u64.wrappingAdd(value, 11400714819323198485))\n  let spread = u64.wrappingMultiply(mingled, 13787848793156543929)\n  return u64.bitXor(spread, u64.shiftRight(spread, 27))\n}\n\n/// A key holding one unsigned integer.\n///\n/// # Details\n///\n/// The scalar types cannot carry a `HashKey` witness themselves: a conformance whose provider is a\n/// scalar admits a sealed compiler operation and nothing else, and no compiler operation computes a\n/// hash — nor may one be added. A key built from an integer is therefore a declared type, and this\n/// is the canonical one.\npub struct Word {\n  /// The integer this key stands for.\n  pub value: u64\n}\n\nimpl Copy for Word {}\n\n/// Constructs an integer key.\npub fn word(value: u64) -> Word {\n  return Word { value: value }\n}\n\nfn wordEquals(left: &Word, right: &Word) -> bool {\n  return left.value == right.value\n}\n\nfn wordHash(value: &Word, seed: &HashSeed) -> u64 {\n  return mix(seed, value.value)\n}\n\nimpl HashKey for Word { equals: Word.wordEquals hash: Word.wordHash }\n",
