    source:
      "//! Explicit access to process arguments, environment values, and the working directory as bytes.\n//!\n//! # When to use\n//! Require [`HostInput`] when code needs launch-time process data but should remain replaceable in\n//! tests. Use [`text`] only when the caller wants a checked UTF-8 view; keep the original bytes for\n//! lossless pass-through.\n//!\n//! # Details\n//! Arguments include the program name at index zero and retain host order. A missing argument index\n//! or unset variable is [`None`], while [`HostInputError`] means the provider could not answer.\n//! Returned [`Bytes`] values are independently owned, so lookup operations also carry explicit\n//! [`OutOfMemoryError`] and [`Allocator`] channels.\n//!\n//! The service is read-only and never mutates environment variables or the process working\n//! directory. No ambient global is consulted after a provider is supplied.\n\n// The portable process-input boundary. A program receives its command line, its environment, and\n// its working directory here, explicitly, and never through an ambient global.\n//\n// Every value this service hands back is raw bytes, exactly as the process received them. A POSIX\n// argument or environment value is an arbitrary byte string, and a program must be able to read one\n// and pass it through unchanged, so the byte view is the primary one. `text` is the checked,\n// fallible view for the common case; it never replaces or discards the bytes.\n\nimport silk.bytes { Bytes }\nimport silk.core { Allocator }\nimport silk.core { OutOfMemoryError }\nimport silk.option { None, Option, Some }\nimport silk.result { Result }\nimport silk.string { InvalidUtf8, fromUtf8 as stringFromUtf8, utf8Bytes as stringUtf8Bytes }\nimport silk.u8 as u8\nimport silk.usize as usize\nimport silk.vector { Vector, append as vectorAppend, make as vectorMake }\n\n/// Failure to complete one host-input lookup.\npub struct HostInputError {}\n\n/// Constructs the typed failure of one host lookup that could not complete.\npub fn inputFailure() -> HostInputError {\n  return HostInputError {}\n}\n\n/// Portable read-only process-input contract.\n///\n/// # Details\n///\n/// The service reads and never writes: it has no operation that sets an environment variable or\n/// changes the working directory. An absent argument index and an unset variable name are `None`\n/// rather than typed failures, because absence is an ordinary answer; only a host that cannot\n/// answer at all is `HostInputError`.\npub service HostInput {\n  /// The number of command-line arguments the process received, including the program name at\n  /// index zero.\n  effect fn argumentCount() -> usize ! HostInputError ? &mut HostInput\n  /// The raw bytes of one argument, or `None` at or past the argument count.\n  effect fn argument(\n    index: usize\n  ) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator\n  /// The raw bytes of one environment variable's value, or `None` when the name is unset.\n  effect fn variable(\n    name: &[u8]\n  ) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator\n  /// The raw bytes of the process working directory.\n  effect fn workingDirectory() -> Bytes ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator\n}\n\n/// Builds the argument-count effect.\npub effect fn argumentCount() -> usize ! HostInputError ? &mut HostInput {\n  return run HostInput.argumentCount()\n}\n\n/// Builds one argument lookup effect.\npub effect fn argument(\n  index: usize\n) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator {\n  return run HostInput.argument(index)\n}\n\n/// Builds one environment lookup effect for a raw byte name.\npub effect fn variable(\n  name: &[u8]\n) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator {\n  return run HostInput.variable(name)\n}\n\n/// Looks one environment variable up by its textual name.\npub effect fn variableNamed(\n  name: string\n) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator {\n  return run HostInput.variable(stringUtf8Bytes(name))\n}\n\n/// Builds the working-directory effect.\npub effect fn workingDirectory() -> Bytes ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator {\n  return run HostInput.workingDirectory()\n}\n\neffect fn missingArgument() -> Bytes ! HostInputError {\n  fail inputFailure()\n}\n\n/// Collects every command-line argument, in the order the process received them.\n///\n/// # Details\n///\n/// A host that reports a count it cannot then supply is a broken host, so a missing index below the\n/// count is `HostInputError` rather than a silently shorter sequence.\npub effect fn arguments(\n) -> Vector<Bytes> ! HostInputError | OutOfMemoryError ? &mut HostInput | &mut Allocator {\n  let total = run HostInput.argumentCount()\n  let mut collected = vectorMake<Bytes>()\n  let mut index = usize.ZERO\n  while index < total {\n    let found = run HostInput.argument(index)\n    let owned = match move found {\n      Some<Bytes> { value: bytes } => move bytes\n      None {} => run missingArgument()\n    }\n    let appended = run vectorAppend<Bytes>(&mut collected, move owned)\n    index = index + usize.ONE\n  }\n  return move collected\n}\n\n/// Returns the checked textual view of raw host bytes.\n///\n/// # Details\n///\n/// Host input is not required to be UTF-8, so the view is fallible. A failure leaves the bytes\n/// untouched and readable, which is how a program passes a value it cannot decode through unchanged.\npub fn text(values: &[u8]) -> Result<string, InvalidUtf8> {\n  return stringFromUtf8(values)\n}\n",
