    source:
      '//! Checked size-and-alignment descriptions used to request storage from an allocator.\n//!\n//! # When to use\n//! Prefer [`of`] when storage will hold a known Silk type. Use [`make`] only at an untyped boundary\n//! that already knows a byte size and alignment, and [`repeat`] when sizing contiguous elements.\n//!\n//! # Details\n//! Alignments are non-zero powers of two. [`repeat`] preserves the element alignment and reports\n//! [`LayoutOverflow`] instead of wrapping the aggregate byte size. A [`Layout`] describes storage;\n//! it does not allocate or initialize it.\n\nimport silk.option { None }\nimport silk.option { Some }\nimport silk.usize as usize\n\n/// A byte size paired with a non-zero power-of-two alignment.\npub struct Layout {\n  /// The number of addressable bytes required by the described storage.\n  pub bytes: usize\n  /// The required non-zero power-of-two byte alignment.\n  pub alignment: usize\n}\n\n/// Reports the rejected alignment supplied to [`make`].\npub struct InvalidAlignment {\n  /// The zero or non-power-of-two alignment that was rejected.\n  pub alignment: usize\n}\n\n/// Reports that [`repeat`] could not represent the aggregate byte size as `usize`.\npub struct LayoutOverflow {}\n\n/// Returns the compiler-selected layout of T.\npub fn of<T>() -> Layout {\n  return Intrinsic.layoutOf<T>()\n}\n\n/// Constructs a layout from an explicit size and alignment.\npub fn make(size: usize, alignment: usize) -> Layout | InvalidAlignment {\n  if alignment == 0 {\n    return InvalidAlignment { alignment: alignment }\n  }\n  let previous = alignment - 1\n  if usize.bitAnd(alignment, previous) != 0 {\n    return InvalidAlignment { alignment: alignment }\n  }\n  return Layout { bytes: size, alignment: alignment }\n}\n\n/// Repeats a layout with checked aggregate-size semantics.\npub fn repeat(layout: Layout, count: usize) -> Layout | LayoutOverflow {\n  return match move usize.checkedMultiply(layout.bytes, count) {\n    None {} => LayoutOverflow {}\n    Some<usize> { value } => Layout { bytes: value, alignment: layout.alignment }\n  }\n}\n',
