    source:
      "//! Compile-time ordering witnesses and a three-way result derived from strict comparison.\n//!\n//! # When to use\n//! Add an [`Order`] bound when a generic algorithm needs `<`, as sorting and binary search do. Use\n//! [`compare`] when all three outcomes matter, or [`less`] and [`equal`] for predicates.\n//!\n//! # Details\n//! An interface witness is selected during specialization; it creates no service requirement or\n//! runtime dispatch. [`Equal`] means neither operand orders before the other, so equality cannot\n//! disagree with the witness's own strict ordering. Witness implementations must provide a\n//! consistent strict order for algorithms to behave predictably.\n\n// The comparison contract the ordered sequence operations resolve against. Ordinary Silk: the\n// interface selects a compiler-known comparison during specialization exactly as `Integer` does, and\n// creates no effect requirement, provider slot, or runtime dispatch.\n//\n// The contract is `lessThan` rather than a three-way `compare` because an interface operation is\n// reachable from a generic body only through the operator that spells it. `<` spells `lessThan`, so\n// a body bounded by `Order` can compare; no operator spells `compare`, so a `compare` operation\n// would be declared and mapped yet uncallable. The three-way result is derived here instead, from\n// the two strict comparisons, and is therefore ordinary Silk over the same one-operation bound.\n\nimport silk.bool as bool\nimport silk.i16 as i16\nimport silk.i32 as i32\nimport silk.i64 as i64\nimport silk.i8 as i8\nimport silk.isize as isize\nimport silk.u16 as u16\nimport silk.u32 as u32\nimport silk.u64 as u64\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// The left value orders before the right value.\npub struct Less {}\n\n/// Neither value orders before the other.\npub struct Equal {}\n\n/// The left value orders after the right value.\npub struct Greater {}\n\n/// The result of comparing two values in one order.\npub struct Ordering {\n  /// The comparison result, narrowed with `match`.\n  pub value: Less | Equal | Greater\n}\n\n/// Static strict-ordering contract for primitive comparable values.\n///\n/// # Details\n///\n/// A witness supplies the strict `lessThan` the operator `<` spells. Equality is derived from it\n/// rather than declared, so a witness can never disagree with itself about which values are equal.\npub interface Order {\n  /// Reports whether `left` orders strictly before `right`.\n  operator < fn lessThan(left: &Self, right: &Self) -> bool\n}\n\nimpl Order for u8 { lessThan: Intrinsic.u8LessThan }\nimpl Order for u16 { lessThan: Intrinsic.u16LessThan }\nimpl Order for u32 { lessThan: Intrinsic.u32LessThan }\nimpl Order for u64 { lessThan: Intrinsic.u64LessThan }\nimpl Order for usize { lessThan: Intrinsic.usizeLessThan }\nimpl Order for i8 { lessThan: Intrinsic.i8LessThan }\nimpl Order for i16 { lessThan: Intrinsic.i16LessThan }\nimpl Order for i32 { lessThan: Intrinsic.i32LessThan }\nimpl Order for i64 { lessThan: Intrinsic.i64LessThan }\nimpl Order for isize { lessThan: Intrinsic.isizeLessThan }\n\n/// Compares two values three ways using the concrete comparison selected during specialization.\n///\n/// # Details\n///\n/// Reads both operands twice without moving either, so the result is the same whichever order a\n/// caller evaluates the operands in.\npub fn compare<T: Order>(left: T, right: T) -> Ordering {\n  if (&left) < (&right) {\n    return Ordering { value: Less {} }\n  }\n  if (&right) < (&left) {\n    return Ordering { value: Greater {} }\n  }\n  return Ordering { value: Equal {} }\n}\n\n/// Reports whether one value orders strictly before another.\npub fn less<T: Order>(left: T, right: T) -> bool {\n  return (&left) < (&right)\n}\n\n/// Reports whether neither value orders before the other.\npub fn equal<T: Order>(left: T, right: T) -> bool {\n  if (&left) < (&right) {\n    return false\n  }\n  return !((&right) < (&left))\n}\n\n/// Reports whether an ordering is `Less`.\npub fn isLess(ordering: &Ordering) -> bool {\n  return match &ordering.value {\n    Less {} => true\n    Equal {} => false\n    Greater {} => false\n  }\n}\n\n/// Reports whether an ordering is `Equal`.\npub fn isEqual(ordering: &Ordering) -> bool {\n  return match &ordering.value {\n    Less {} => false\n    Equal {} => true\n    Greater {} => false\n  }\n}\n\n/// Reports whether an ordering is `Greater`.\npub fn isGreater(ordering: &Ordering) -> bool {\n  return match &ordering.value {\n    Less {} => false\n    Equal {} => false\n    Greater {} => true\n  }\n}\n",
