    source:
      '//! Native [`HostInput`] provider for the process command line, environment, and working directory.\n//!\n//! # When to use\n//! Construct [`OsHostInput`] at a native application edge and provide it to portable code requiring\n//! [`HostInput`]. Tests can replace it with a deterministic provider and keep process state out of\n//! the program under test.\n//!\n//! # Details\n//! The provider owns no persistent state. Each successful lookup copies the host value into\n//! independent [`Bytes`], beginning with a bounded buffer and retrying once at the exact size the\n//! boundary reports. An absent argument or variable remains [`None`]; an unavailable working\n//! directory and contradictory host lengths become [`HostInputError`].\n//!\n//! # Gotchas\n//! Reachable OS host-input operations are native-only. Direct WebAssembly compilation rejects them\n//! instead of inventing process-global imports; evaluator execution requires an injected adapter.\n\nimport silk.bool as bool\nimport silk.bytes {\n  Bytes,\n  append as bytesAppend,\n  asMutSlice as bytesMutSlice,\n  asSlice as bytesSlice,\n  length as bytesLength,\n  make as bytesMake,\n  zeroed as bytesZeroed\n}\nimport silk.core { Allocator }\nimport silk.core { OutOfMemoryError }\nimport silk.host_input { HostInput, HostInputError, inputFailure }\nimport silk.i32 as i32\nimport silk.option { None, Option, Some, none, some }\nimport silk.string { utf8Bytes as stringUtf8Bytes }\nimport silk.u32 as u32\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// Native provider reading the process command line, environment, and working directory. It owns no\n/// state; all three belong to the process rather than to the value.\npub struct OsHostInput {}\n\n/// Constructs the process-backed input provider.\npub fn make() -> OsHostInput {\n  return OsHostInput {}\n}\n\neffect fn raise() -> never ! HostInputError {\n  fail inputFailure()\n}\n\neffect fn rawArgumentCount(count: &mut usize, lowReason: &mut i32, nativeCode: &mut u32) -> bool {\n  unsafe { return run Intrinsic.osHostArgumentCount(count, lowReason, nativeCode) }\n  return false\n}\n\neffect fn rawArgument(\n  index: usize,\n  output: &mut [u8],\n  lowReason: &mut i32,\n  nativeCode: &mut u32\n) -> Option<usize> {\n  unsafe { return run Intrinsic.osHostArgument(index, output, lowReason, nativeCode) }\n  let impossible = 1 / 0\n  return none<usize>()\n}\n\neffect fn rawVariable(\n  name: &[u8],\n  output: &mut [u8],\n  lowReason: &mut i32,\n  nativeCode: &mut u32\n) -> Option<usize> {\n  unsafe { return run Intrinsic.osHostVariable(name, output, lowReason, nativeCode) }\n  let impossible = 1 / 0\n  return none<usize>()\n}\n\neffect fn rawWorkingDirectory(\n  output: &mut [u8],\n  lowReason: &mut i32,\n  nativeCode: &mut u32\n) -> Option<usize> {\n  unsafe { return run Intrinsic.osHostWorkingDirectory(output, lowReason, nativeCode) }\n  let impossible = 1 / 0\n  return none<usize>()\n}\n\neffect fn ownedPrefix(view: &[u8], length: usize) -> Bytes ! OutOfMemoryError ? &mut Allocator {\n  let mut result = bytesMake()\n  let mut index = usize.ZERO\n  while index < length {\n    let one = [view[index]]\n    let appended = run bytesAppend(&mut result, &one)\n    index = index + usize.ONE\n  }\n  return move result\n}\n\n/// Copies one host value into independently owned bytes, growing the buffer once when needed.\n///\n/// The low-level boundary reports the value\'s complete byte length even when the buffer it received\n/// was too small, so a second pass with an exactly sized buffer always completes. An absent value is\n/// `None` with the not-found reason; any other reason is a host error.\neffect fn fetch(\n  selector: i32,\n  index: usize,\n  name: &[u8]\n) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut Allocator {\n  let initial = bytesZeroed(128)\n  let mut buffer = run initial\n  let mut result = none<Bytes>()\n  let mut complete = false\n  let mut grown = false\n  while complete == false {\n    let mut lowReason = 0\n    let mut nativeCode = u32.toU32(0)\n    let mut received = none<usize>()\n    if selector == 0 {\n      received = run rawArgument(index, bytesMutSlice(&mut buffer), &mut lowReason, &mut nativeCode)\n    } else {\n      if selector == 1 {\n        received = run rawVariable(name, bytesMutSlice(&mut buffer), &mut lowReason, &mut nativeCode)\n      } else {\n        received = run rawWorkingDirectory(bytesMutSlice(&mut buffer), &mut lowReason, &mut nativeCode)\n      }\n    }\n    let encoded = match move received {\n      Some<usize> { value: total } => total + usize.ONE\n      None {} => usize.ZERO\n    }\n    if encoded == usize.ZERO {\n      if lowReason != 0 { return run raise() }\n      complete = true\n    } else {\n      let total = encoded - usize.ONE\n      if total <= bytesLength(&buffer) {\n        let owned = run ownedPrefix(bytesSlice(&buffer), total)\n        result = some<Bytes>(move owned)\n        complete = true\n      } else {\n        // An exactly sized buffer completes an honest host in one more pass, so a second short\n        // answer means the host contradicted the length it just reported.\n        if grown { return run raise() }\n        grown = true\n        let resized = bytesZeroed(total)\n        buffer = run resized\n      }\n    }\n  }\n  return move result\n}\n\n/// Reports how many arguments the process received, including the program name at index zero.\neffect fn argumentCount(self: &mut OsHostInput) -> usize ! HostInputError {\n  let mut count = usize.ZERO\n  let mut lowReason = 0\n  let mut nativeCode = u32.toU32(0)\n  let answered = run rawArgumentCount(&mut count, &mut lowReason, &mut nativeCode)\n  if answered == false { return run raise() }\n  return count\n}\n\n/// Copies one argument\'s raw bytes, exactly as the process received them.\neffect fn argument(\n  self: &mut OsHostInput,\n  index: usize\n) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut Allocator {\n  return run fetch(0, index, stringUtf8Bytes(""))\n}\n\n/// Copies one environment value\'s raw bytes. An unset name is `None` rather than a failure.\neffect fn variable(\n  self: &mut OsHostInput,\n  name: &[u8]\n) -> Option<Bytes> ! HostInputError | OutOfMemoryError ? &mut Allocator {\n  return run fetch(1, usize.ZERO, name)\n}\n\n/// Copies the process working directory\'s raw bytes. It always exists, so absence is a host error.\neffect fn workingDirectory(\n  self: &mut OsHostInput\n) -> Bytes ! HostInputError | OutOfMemoryError ? &mut Allocator {\n  let found = run fetch(2, usize.ZERO, stringUtf8Bytes(""))\n  return match move found {\n    Some<Bytes> { value: bytes } => move bytes\n    None {} => run raise()\n  }\n}\n\nimpl HostInput for OsHostInput {\n  argumentCount: OsHostInput.argumentCount\n  argument: OsHostInput.argument\n  variable: OsHostInput.variable\n  workingDirectory: OsHostInput.workingDirectory\n}\n',
