    source:
      "//! Native [`StandardInput`] provider backed by the process standard-input descriptor.\n//!\n//! # When to use\n//! Construct [`OsStandardInput`] at a native application edge and provide it to portable byte-input\n//! code. Use a scripted provider in tests to control partial reads, end-of-input, and failures.\n//!\n//! # Details\n//! The provider owns no persistent state and commits each host read directly into the caller's\n//! buffer. A zero-length host transfer becomes the outcome selected by [`endOfInput`]; only a host\n//! read error becomes [`StreamReadError`]. Partial transfer counts are preserved exactly.\n//!\n//! # Gotchas\n//! Reachable OS standard-input operations are native-only. Direct WebAssembly compilation rejects\n//! them rather than inventing a descriptor import; evaluator execution requires an injected adapter.\n\nimport silk.i32 as i32\nimport silk.option { None, Option, Some, none }\nimport silk.standard_input {\n  ReadOutcome,\n  StandardInput,\n  StreamReadError,\n  endOfInput,\n  filled,\n  readFailure\n}\nimport silk.u32 as u32\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// Native provider reading the process standard-input descriptor. It owns no state; the descriptor\n/// belongs to the process rather than to the value.\npub struct OsStandardInput {}\n\n/// Constructs the process-backed byte-input provider.\npub fn make() -> OsStandardInput {\n  return OsStandardInput {}\n}\n\neffect fn rawRead(output: &mut [u8], lowReason: &mut i32, nativeCode: &mut u32) -> Option<usize> {\n  unsafe { return run Intrinsic.osStandardInputRead(output, lowReason, nativeCode) }\n  let impossible = 1 / 0\n  return none<usize>()\n}\n\neffect fn raise() -> never ! StreamReadError {\n  fail readFailure()\n}\n\n/// Commits one host read into the caller's buffer.\n///\n/// The low-level boundary reports a zero-length transfer for the end of input, which becomes\n/// `EndOfInput` data rather than a typed failure. Only a host error becomes `StreamReadError`.\neffect fn read(self: &mut OsStandardInput, buffer: &mut [u8]) -> ReadOutcome ! StreamReadError {\n  let mut lowReason = 0\n  let mut nativeCode = u32.toU32(0)\n  let received = run rawRead(move buffer, &mut lowReason, &mut nativeCode)\n  let length = match move received {\n    None {} => run raise()\n    Some<usize> { value: selected } => selected\n  }\n  if length == usize.ZERO { return endOfInput() }\n  return filled(length)\n}\n\nimpl StandardInput for OsStandardInput {\n  read: OsStandardInput.read\n}\n",
