    source:
      '//! Low-level typed views over owned allocations for implementing collections and storage actors.\n//!\n//! # When to use\n//! Prefer `silk.vector.Vector`, `silk.bytes.Bytes`, or `silk.box.Box` in application code. Use\n//! these operations only when building a container that explicitly tracks capacity and which\n//! slots are initialized.\n//!\n//! # Details\n//! [`copy`] supports overlapping ranges and behaves as though the moved elements passed through\n//! temporary storage. [`fill`] writes raw bytes and therefore operates only on `RawBuffer<u8>`.\n//!\n//! # Gotchas\n//! These wrappers are unchecked. The caller must prove that an allocation fits the recorded\n//! element count, every selected range is in bounds, and every read or view covers initialized\n//! elements. Releasing a raw buffer releases its allocation but does not discover and drop values\n//! still stored in it; a container must clear initialized `Slot` values before release.\n\nimport silk.slot as Slot\nimport silk.u8 as u8\nimport silk.usize as usize\n\n/// Adopts an allocation as typed raw storage. The caller proves the count fits the allocation.\npub fn from<T>(allocation: Allocation, count: usize) -> RawBuffer<T> {\n  unsafe { return Intrinsic.rawBufferFrom<T>(move allocation, count) }\n}\n\n/// Selects one unchecked storage slot. The caller proves the index is in bounds.\npub fn slot<T>(buffer: &mut RawBuffer<T>, index: usize) -> Slot<T> {\n  unsafe { return Intrinsic.rawBufferSlot<T>(buffer, index) }\n}\n\n/// Returns the element capacity recorded by a raw buffer.\npub fn count<T>(buffer: &RawBuffer<T>) -> usize {\n  return Intrinsic.rawBufferCount<T>(buffer)\n}\n\n/// Reads an unchecked initialized element. The caller proves initialization and bounds.\npub fn read<T: Copy>(buffer: &RawBuffer<T>, index: usize) -> T {\n  unsafe { return Intrinsic.rawBufferRead<T>(buffer, index) }\n}\n\n/// Moves a caller-proven initialized range into selected storage in one bulk transfer.\n///\n/// # Details\n///\n/// Source and destination may overlap; the result is as if the elements travelled through an\n/// intermediate buffer.\npub fn copy<T>(destination: &mut RawBuffer<T>, destinationOffset: usize, source: &[T], length: usize) -> () {\n  unsafe { return Intrinsic.rawBufferCopy<T>(destination, destinationOffset, source, length) }\n}\n\n/// Sets a caller-proven byte range of raw storage to one repeated byte value.\npub fn fill(buffer: &mut RawBuffer<u8>, offset: usize, length: usize, value: u8) -> () {\n  unsafe { return Intrinsic.rawBufferFill(buffer, offset, length, value) }\n}\n\n/// Forms a shared view over caller-proven initialized elements in the selected range.\npub fn view<T>(buffer: &RawBuffer<T>, offset: usize, length: usize) -> &[T] {\n  unsafe { return Intrinsic.rawBufferView<T>(buffer, offset, length) }\n}\n\n/// Forms an exclusive view over caller-proven initialized elements in the selected range.\npub fn viewMut<T>(buffer: &mut RawBuffer<T>, offset: usize, length: usize) -> &mut [T] {\n  unsafe { return Intrinsic.rawBufferViewMut<T>(buffer, offset, length) }\n}\n',
